SELECT country, CASE WHEN city IN ('Tokyo', 'Berlin') THEN 'group_a' ELSE 'other' END AS city_group, CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN city = 'Berlin' THEN rating ELSE 0 END) AS berlin_rating FROM suppliers WHERE city = 'London' GROUP BY country, CASE WHEN city IN ('Tokyo', 'Berlin') THEN 'group_a' ELSE 'other' END, CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END HAVING AVG(rating) >= 3.2 ORDER BY city_group DESC, country, rating_bucket LIMIT 5
